                ['title' => 'Travel to Chitwan', 'location' => 'Kathmandu or Pokhara to Chitwan', 'altitude_meters' => 500, 'activity_label' => 'Road transfer and lodge check-in', 'meal_plan' => 'Lunch, dinner', 'description' => 'Travel to the Terai and check in at the lodge. Review park rules and the planned activities with your local naturalist.'],
                ['title' => 'Explore the park and river habitats', 'location' => 'Chitwan National Park buffer zone', 'altitude_meters' => 500, 'activity_label' => 'Guided nature activities', 'meal_plan' => 'Breakfast, lunch, dinner', 'description' => 'Join the activities available that day, which may include a guided nature walk, canoe experience, or responsible wildlife viewing. Activities follow park rules and local conditions.'],
                ['title' => 'Morning nature walk and departure', 'location' => 'Chitwan to onward destination', 'altitude_meters' => 500, 'activity_label' => 'Morning activity and transfer', 'meal_plan' => 'Breakfast', 'description' => 'Take a final guided morning activity if conditions allow, then transfer to your next destination.'],
            ],
        ];

        foreach ($itineraries as $packageName => $days) {
            $package = Package::query()->where('name', $packageName)->firstOrFail();

            if ($package->itineraryDays()->exists()) {
                continue;
            }

            $package->itineraryDays()->createMany(array_map(
                fn (array $day, int $index): array => [
                    ...$day,
                    'day_number' => $index + 1,
                    'sort_order' => $index,
                ],
                $days,
                array_keys($days),
            ));
        }
    }
}
